# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: formats the Python the inline AI proposes (inline_edit.py) with ruff, so a
#          proposal reads as the repo's code does. SQL has no formatter here: the
#          model is told the layout instead (inline_edit.SQL_FORMAT).
# Usage: format_python("x=1")  ->  "x = 1"; code ruff can't format (a fragment of a
#        statement, a cell magic) comes back unchanged. Needs the ruff package.
# ---------------------------------------------------------------------------
from __future__ import annotations

import subprocess
import sys
import textwrap

# narrower than the repo's 120: a cell is often shown beside other panels (the user's pick)
LINE_LENGTH = 88
TIMEOUT_S = 5


def format_python(code: str) -> str:
    """The code as `ruff format` writes it, at LINE_LENGTH; unchanged when ruff can't (never
    raises). An indented block (a selection inside a function) is formatted as if it started at
    the margin, then given its indent back. Whether the text ends with a newline is kept.
    """
    if not code.strip():
        return code
    flat = textwrap.dedent(code)
    first = next(line for line in code.splitlines() if line.strip())
    indent = first[: len(first) - len(first.lstrip())] if flat != code else ""
    try:
        # --isolated: ruff's own defaults, whatever folder the app was started in
        # a fixed command; the code goes in on stdin
        width = str(LINE_LENGTH - len(indent))
        done = subprocess.run(
            [sys.executable, "-m", "ruff", "format", "--isolated", "--line-length", width, "-"],
            input=flat,
            capture_output=True,
            text=True,
            timeout=TIMEOUT_S,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        return code
    if done.returncode != 0:
        return code
    pretty = textwrap.indent(done.stdout, indent) if indent else done.stdout
    return pretty if code.endswith("\n") else pretty.rstrip("\n")
